--

CREATE TABLE public.activityevents (
    id bigint NOT NULL,
    "eventType" character varying(255) NOT NULL,
    source character varying(255) NOT NULL,
    "actorType" character varying(255) NOT NULL,
    "actorId" bigint,
    "subjectType" character varying(255),
    "subjectId" character varying(255),
    "siteId" bigint,
    "rootEventId" bigint,
    payload jsonb NOT NULL,
    "occurredAt" timestamp(0) without time zone NOT NULL
);


